function v({registerIndicator:d,nulls:F}){d({id:"oa-fi",name:"Force Index (FI)",category:"Oscillators",placement:"pane",inputs:[{key:"period",type:"number",label:"Period",default:13,min:1,max:500,step:1}],plots:[{key:"fi",type:"line",title:"Force Index",style:{color:"#ffeb3b",lineWidth:2}}],levels:()=>[{price:0,title:"Zero",color:"#787b86",dashed:!0}],calc(t,N){const h=Math.min(500,Math.max(1,Math.floor(Number(N.period)||13))),n=t.length,s=2/(h+1),a=1-s,c=new Array(n).fill(NaN);let l=0,o=1,u=!0,f=!0,i=NaN;for(let e=0;e<n;e++){const m=Number.isFinite(t[e].close)?t[e].close:0,y=Number.isFinite(t[e].volume)?t[e].volume:0,p=Number.isFinite(i)?(m-i)*y:0;i=m,f?(l=p,f=!1):l=s*p+a*l;let r;if(u){o=o*a;const b=o>1e-10?1/(1-o):1;r=l*b,o<=1e-10&&(u=!1)}else r=l;c[e]=r}return{fi:F(c)}}})}export{v as default};
